420  static void
   421  cmd_data_start_input(struct smtp_server_cmd_ctx *cmd,
   422                       struct cmd_data_context *data_cmd, struct istream *input)
   423  {
   424          struct smtp_server_connection *conn = cmd->conn;
   425          struct smtp_server_command *command = cmd->cmd;
   426
   427          i_assert(data_cmd != NULL);
   428
   429          if (input != NULL) {
   430                  conn->state.data_input = input;
   431                  i_stream_ref(input);
   432          }
   433
   434          if (data_cmd->client_input)
   435                  smtp_server_command_input_lock(cmd);
   436
   437          if (data_cmd->chunk_last) {
   438                  smtp_server_command_add_hook(
   439                          command, SMTP_SERVER_COMMAND_HOOK_COMPLETED,
   440                          cmd_data_completed, data_cmd);
   441          } else {
   442                  smtp_server_command_add_hook(
   443                          command, SMTP_SERVER_COMMAND_HOOK_COMPLETED,
   444                          cmd_data_chunk_completed, data_cmd);
   445          }
   446
   447          if (conn->state.pending_mail_cmds == 0 &&
   448                  conn->state.pending_rcpt_cmds == 0) {
   449                  cmd_data_next(cmd, data_cmd);
   450          } else {
   451                  smtp_server_command_add_hook(
   452                          command, SMTP_SERVER_COMMAND_HOOK_NEXT,
   453                          cmd_data_next, data_cmd);
   454          }
   455  }
