   457  /* DATA command */
   458
   459  static void
   460  cmd_data_start(struct smtp_server_cmd_ctx *cmd,
   461                 struct cmd_data_context *data_cmd)
   462  {
   463          struct smtp_server_connection *conn = cmd->conn;
   464          struct smtp_server_transaction *trans = conn->state.trans;
   465          struct istream *dot_input;
   466
   467          /* called when all previous commands were finished */
   468          i_assert(conn->state.pending_mail_cmds == 0 &&
   469                  conn->state.pending_rcpt_cmds == 0);
   470
   471          /* this is the one and only data command */
   472          if (trans != NULL)
   473                  smtp_server_transaction_last_data(trans, cmd);
   474
   475          /* check whether we have had successful mail and rcpt commands */
   476          if (!smtp_server_connection_data_check_state(cmd))
   477                  return;
   478
   479          /* don't allow classic DATA when CHUNKING sequence was started before */
   480          if (conn->state.data_chunks > 0) {
   481                  smtp_server_command_fail(cmd->cmd,
   482                          503, "5.5.0", "Bad sequence of commands");
   483                  return;
   484          }
   485
   486          smtp_server_connection_set_state(conn, SMTP_SERVER_STATE_DATA, NULL);
   487
   488          /* confirm initial success to client */
   489          smtp_server_connection_reply_immediate(conn, 354, "OK");
   490
   491          /* start reading message data from client */
   492          dot_input = smtp_command_parse_data_with_dot(conn->smtp_parser);
   493          cmd_data_start_input(cmd, data_cmd, dot_input);
   494          i_stream_unref(&dot_input);
   495  }
