   531  /* BDAT/B... commands */
   532
   533  void smtp_server_connection_data_chunk_init(struct smtp_server_cmd_ctx *cmd)
   534  {
   535          struct smtp_server_connection *conn = cmd->conn;
   536          struct smtp_server_command *command = cmd->cmd;
   537          struct cmd_data_context *data_cmd;
   538
   539          data_cmd = p_new(cmd->pool, struct cmd_data_context, 1);
   540          data_cmd->chunking = TRUE;
   541          data_cmd->chunk_first = (conn->state.data_chunks++ == 0);
   542          command->data = data_cmd;
   543
   544          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_REPLIED,
   545                                       cmd_data_chunk_replied, data_cmd);
   546          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_DESTROY,
   547                                       cmd_data_destroy, data_cmd);
   548
   549          conn->state.pending_data_cmds++;
   550
   551          if (!conn->state.data_failed && conn->state.data_chain == NULL) {
   552                  i_assert(data_cmd->chunk_first);
   553                  i_assert(conn->state.data_chain_input == NULL);
   554                  conn->state.data_chain_input =
   555                          i_stream_create_chain(&conn->state.data_chain);
   556          }
   557  }
